const express = require('express');
const session = require('express-session');
const PgSession = require('connect-pg-simple')(session);
const { authenticateRequest } = require('./auth');

const app = express();
const sessionStore = new PgSession({ conString: process.env.DATABASE_URL });

app.delete('/api/sessions/:sid', authenticateRequest, (req, res) => {
  const { sid } = req.params;

  // Retrieve session first to verify ownership before destroying
  sessionStore.get(sid, (err, sess) => {
    if (err || !sess) {
      return res.status(404).json({ error: 'Session not found' });
    }

    if (sess.user?.id !== req.user.id && !req.user.isAdmin) {
      return res.status(403).json({ error: 'Forbidden: cannot terminate another user session' });
    }

    sessionStore.destroy(sid, (destroyErr) => {
      if (destroyErr) {
        return res.status(500).json({ error: 'Failed to terminate session' });
      }
      res.json({ message: 'Session terminated successfully', sid });
    });
  });
});

app.listen(8099);
